/* === AI FinOps Dynamics — Shared Base Styles === */
/* v0.4 — Extracted from 10 individual pages */

/* --- Design Tokens --- */
:root {
  /* Dark theme */
  --bg: #070A0F;
  --bg2: #0B111A;
  --bg3: #101722;
  --bg4: #1B2637;
  --b: rgba(148,163,184,0.14);
  --ba: rgba(148,163,184,0.24);
  --t: #F8FAFC;
  --t2: #CBD5E1;
  --t3: #718096;
  --ac: #22D3EE;
  --am: #F59E0B;
  --cy: #38BDF8;
  --success: #22C55E;
  --danger: #EF4444;
  --panel-shadow: 0 22px 70px rgba(0,0,0,0.28);
  --ring: rgba(34,211,238,0.24);
}

/* --- Light theme overrides (toggled by JS) --- */
body.light,
body.light { --bg:#f8fafc;--bg2:#eef3f8;--bg3:#ffffff;--bg4:#e2e8f0;--b:rgba(15,23,42,0.10);--ba:rgba(15,23,42,0.16);--t:#0f172a;--t2:#334155;--t3:#52525b;--ac:#0891B2;--am:#B45309;--cy:#0284C7;--success:#16A34A;--danger:#DC2626;--ring:rgba(8,145,178,0.20);--panel-shadow:0 20px 56px rgba(15,23,42,0.10); }

/* --- Reset --- */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
  background:
    radial-gradient(circle at 16% -10%,rgba(34,211,238,0.12),transparent 32rem),
    radial-gradient(circle at 88% 8%,rgba(245,158,11,0.08),transparent 28rem),
    linear-gradient(180deg,var(--bg),#05070A 62%,var(--bg));
  color:var(--t);
  line-height:1.65;
  -webkit-font-smoothing:antialiased;
  font-size:0.95rem;
  text-rendering:optimizeLegibility;
}
body.light{
  background:
    radial-gradient(circle at 16% -10%,rgba(34,211,238,0.14),transparent 32rem),
    radial-gradient(circle at 88% 8%,rgba(245,158,11,0.10),transparent 28rem),
    linear-gradient(180deg,#f8fafc,#eef3f8 62%,#f8fafc);
}

/* --- Typography --- */
h1{font-size:clamp(2.4rem,6vw,4.8rem);font-weight:850;letter-spacing:-0.06em;line-height:0.96;color:var(--t);margin-bottom:0.85rem}
h2{font-size:clamp(1.65rem,3.4vw,2.7rem);font-weight:800;letter-spacing:-0.04em;line-height:1.05;color:var(--t);margin:2rem 0 0.85rem}
h3{font-weight:700;font-size:1.04rem;color:var(--t);margin:1.5rem 0 0.5rem;letter-spacing:-0.015em}
p{font-size:0.95rem;color:var(--t2);margin-bottom:1rem}
a{color:var(--ac);text-decoration:none}
a:hover{text-decoration:underline}
.lead{font-size:1rem;color:var(--t2);max-width:720px;line-height:1.7;margin-bottom:1.5rem}

body.light h1,body.light h2{color:#111}
body.light .card,
body.light .entry-card,
body.light .trust-card,
body.light .stat,
body.light .proof-ledger,
body.light .receipt,
body.light .chapter{
  background:linear-gradient(180deg,#ffffff,#f8fafc);
}
body.light .comparison-panel>div{background:#ffffff}
body.light .note,
body.light .highlight-box,
body.light .tbl,
body.light .sec,
body.light .sec.alt{background:rgba(255,255,255,0.82)}
body.light .dossier-hero::before{background:radial-gradient(circle at 70% 30%,rgba(34,211,238,0.16),transparent 28rem),linear-gradient(90deg,rgba(248,250,252,0.96),rgba(248,250,252,0.65))}

/* --- Code --- */
code,p code,li code{
  font-family:"JetBrains Mono",monospace;
  font-size:0.82rem;
  background:var(--bg4);
  padding:0.15em 0.4em;
  border-radius:4px;
  color:var(--ac);
}
pre{
  background:var(--bg4);
  border:1px solid var(--b);
  border-radius:8px;
  padding:0.8rem 1rem;
  overflow-x:auto;
  font-size:0.82rem;
  font-family:"JetBrains Mono",monospace;
  line-height:1.5;
  margin:0.5rem 0 1rem;
}

/* --- Top Navigation Bar --- */
.topbar{
  position:fixed;top:0;left:0;right:0;z-index:150;
  display:flex;justify-content:center;gap:0.35rem;
  padding:0.65rem 1rem;
  background:rgba(7,10,15,0.82);
  backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);
  border-bottom:1px solid var(--b);
  overflow-x:auto;white-space:nowrap;
  scrollbar-width:none;
}
.topbar::-webkit-scrollbar{display:none}
body.light .topbar{background:rgba(255,255,255,0.92)}
.topbar-link{
  color:var(--t2);text-decoration:none;
  font-size:0.75rem;font-weight:700;
  transition:color .2s,background .2s,border-color .2s;
  padding:0.38rem 0.72rem;border-radius:999px;border:1px solid transparent;
}
.topbar-link:hover{color:var(--t);background:rgba(148,163,184,0.08);border-color:var(--b);text-decoration:none}

/* --- Footer --- */
footer{
  padding:3rem 2rem;text-align:center;
  border-top:1px solid var(--b);
  font-size:0.72rem;color:var(--t3);line-height:1.8;
  background:linear-gradient(180deg,transparent,rgba(16,23,34,0.52));
}
footer a{color:var(--ac);text-decoration:none;font-weight:600}
footer a:hover{text-decoration:underline}
body.light footer{background:linear-gradient(180deg,transparent,rgba(226,232,240,0.52))}

/* --- Utility Classes --- */
.mono{font-family:'JetBrains Mono',monospace}
.green{color:var(--success)}.amber{color:var(--am)}.cyan{color:var(--cy)}
.note{
  font-size:0.78rem;color:var(--t3);
  padding:0.7rem 1rem;
  background:rgba(16,23,34,0.72);border:1px solid var(--b);
  border-radius:12px;margin:1rem 0;text-align:center;
}

/* --- Shared Component: Cards --- */
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:1rem;margin:1.4rem 0}
.card{
  background:linear-gradient(180deg,rgba(16,23,34,0.96),rgba(11,17,26,0.96));border:1px solid var(--b);
  border-radius:16px;padding:1.25rem;text-align:left;
  transition:border-color .2s,transform .2s,box-shadow .2s;
  box-shadow:0 1px 0 rgba(255,255,255,0.03) inset;
}
.card:hover{border-color:var(--ba);transform:translateY(-2px);box-shadow:var(--panel-shadow)}
.card h4{font-size:0.82rem;color:var(--ac);margin-bottom:0.55rem;font-family:"JetBrains Mono",monospace;text-transform:uppercase;letter-spacing:0.06em}
.card p,.card li{font-size:0.84rem;color:var(--t2);line-height:1.6}

/* --- Shared Component: Entry Cards --- */
.entry-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1rem;margin:2rem auto;max-width:960px}
.entry-card{background:linear-gradient(180deg,rgba(16,23,34,0.98),rgba(11,17,26,0.98));border:1px solid var(--b);border-radius:18px;padding:1.5rem;text-align:left;transition:border-color .2s,transform .2s,box-shadow .2s;text-decoration:none;display:block;color:inherit}
.entry-card:hover{border-color:var(--ring);transform:translateY(-3px);text-decoration:none;box-shadow:var(--panel-shadow)}
.entry-card h3{color:var(--ac);margin:0 0 0.4rem;font-size:0.95rem}
.entry-card p{font-size:0.82rem;color:var(--t2);line-height:1.55;margin:0}

/* --- Shared Component: Trust Grid --- */
.trust-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin:1.5rem 0}
.trust-card{background:linear-gradient(180deg,rgba(16,23,34,0.96),rgba(11,17,26,0.96));border:1px solid var(--b);border-radius:16px;padding:1.35rem;text-align:left;transition:border-color .2s,transform .2s,box-shadow .2s}
.trust-card:hover{transform:translateY(-2px);border-color:var(--ba);box-shadow:var(--panel-shadow)}
.trust-card h4{font-size:0.86rem;color:var(--t);margin-bottom:0.55rem;font-family:"JetBrains Mono",monospace;text-transform:uppercase;letter-spacing:0.045em}
.trust-card p,.trust-card li{font-size:0.78rem;color:var(--t2);line-height:1.55;margin:0}.trust-card ul{list-style:none;padding:0;margin:0}.trust-card li{margin:0.3rem 0}

/* --- Shared Component: Link Grid --- */
.link-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:0.5rem;margin:1.5rem auto;max-width:700px}
.link-grid a{background:rgba(16,23,34,0.86);border:1px solid var(--b);border-radius:999px;padding:0.7rem 1rem;text-align:center;font-size:0.78rem;font-weight:700;transition:border-color .2s,transform .2s,background .2s;text-decoration:none;color:var(--ac)}
.link-grid a:hover{border-color:var(--ba);transform:translateY(-2px);text-decoration:none}

/* --- Shared Component: Section --- */
.sec{
  padding:4.5rem 2rem;max-width:1040px;margin:0 auto;
  background:rgba(7,10,15,0.55);border-radius:18px;border:1px solid var(--b);
  margin-bottom:1.5rem;
}
.sec.alt{background:rgba(11,17,26,0.72)}

/* --- Shared Component: Highlight Box --- */
.highlight-box{
  background:rgba(16,23,34,0.88);border:1px solid var(--b);border-left:3px solid var(--ac);
  padding:1rem 1.25rem;border-radius:0 14px 14px 0;margin:1rem 0;
}
.highlight-box p{font-size:0.85rem;color:var(--t2);line-height:1.5}
.highlight-box strong{color:var(--t)}

/* --- Shared Component: Tables --- */
.tbl{overflow-x:auto;margin:1.2rem 0;border-radius:14px;border:1px solid var(--b);background:rgba(16,23,34,0.72)}
.tbl table{width:100%;border-collapse:collapse;font-size:0.78rem}
.tbl th{
  text-align:left;padding:0.65rem 0.8rem;
  color:var(--t2);font-weight:600;
  font-size:0.72rem;text-transform:uppercase;letter-spacing:0.5px;
  border-bottom:1px solid var(--ba);background:rgba(27,38,55,0.82);
}
.tbl td{padding:0.58rem 0.8rem;border-bottom:1px solid var(--b);font-size:0.82rem}
.tbl td code,.tbl .mono{font-size:0.72rem}
table{width:100%;border-collapse:collapse;font-size:0.85rem;margin:1rem 0}
th,td{padding:0.6rem 0.75rem;text-align:left;border-bottom:1px solid var(--b)}
th{color:var(--t3);font-weight:500;font-size:0.75rem;text-transform:uppercase;letter-spacing:0.05em}
td{color:var(--t2)}
td code{color:var(--ac)}

/* --- Shared Component: Row / Grid --- */
.row{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:1rem}

/* --- Shared Component: Stat Cards --- */
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1rem;margin:1.6rem 0}
.stat{
  background:linear-gradient(180deg,rgba(16,23,34,0.98),rgba(11,17,26,0.98));border:1px solid var(--b);
  border-radius:16px;padding:1.25rem;text-align:center;
  transition:transform .2s,border-color .2s,box-shadow .2s;
}
.stat:hover{transform:translateY(-2px);border-color:var(--ring);box-shadow:var(--panel-shadow)}
.stat .v{font-size:1.65rem;font-weight:850;color:var(--ac);letter-spacing:-0.04em}
.stat .v.amber{color:var(--am)}
.stat .v.cyan{color:var(--cy)}
.stat .l{font-size:0.65rem;color:var(--t3);text-transform:uppercase;letter-spacing:0.8px;margin-top:0.3rem;font-weight:600}
.stat .s{font-size:0.72rem;color:var(--t2);margin-top:0.15rem;line-height:1.3}

/* --- Shared Component: Key Metric --- */
.met{font-family:"JetBrains Mono",monospace;color:var(--am)}
.tag{display:inline-block;font-size:0.7rem;padding:0.15em 0.5em;border-radius:4px;background:var(--bg4);color:var(--cy);margin-right:0.3rem}

/* --- Visual Hierarchy --- */
.featured-section{padding:4.5rem 2rem;border-left:3px solid var(--ac);background:linear-gradient(135deg,var(--bg3),var(--bg2));border-radius:12px;margin-bottom:1.5rem}
.secondary-section{padding:3rem 2rem;background:var(--bg3);border:1px solid var(--b);border-radius:12px;margin-bottom:1.5rem}
.detail-section{padding:1.5rem 2rem;font-size:0.78rem;color:var(--t3);background:var(--bg4);border:1px solid var(--b);border-radius:8px;margin-bottom:1rem;max-width:960px;margin-left:auto;margin-right:auto}

/* --- CTA Button --- */
.cta-btn{
  display:inline-flex;align-items:center;gap:0.5rem;
  padding:0.78rem 1.6rem;
  background:linear-gradient(135deg,var(--ac),#67E8F9);color:#031016;
  border-radius:100px;font-weight:700;font-size:0.85rem;
  text-decoration:none;transition:all .25s;border:1px solid rgba(255,255,255,0.08);cursor:pointer;
  box-shadow:0 12px 34px rgba(34,211,238,0.18);
}
.cta-btn:hover{transform:translateY(-1px);box-shadow:0 16px 42px rgba(34,211,238,0.28);text-decoration:none}
body.light .cta-btn{box-shadow:0 12px 34px rgba(8,145,178,0.18)}
body.light .cta-btn:hover{box-shadow:0 16px 42px rgba(8,145,178,0.28)}
.cta-btn.ghost{background:transparent;color:var(--t2);border:1px solid var(--ba)}
.cta-btn.ghost:hover{color:var(--t);border-color:var(--ring);box-shadow:none;background:rgba(34,211,238,0.04)}
.cta-btn.big{padding:0.9rem 2.4rem;font-size:0.95rem}
.cta-bar{display:flex;justify-content:center;gap:1rem;margin:1.5rem 0;flex-wrap:wrap}

/* --- Theme Toggle --- */
.theme-toggle{
  position:fixed;bottom:1.5rem;right:1.5rem;z-index:200;
  width:40px;height:40px;border-radius:50%;
  background:var(--bg3);border:1px solid var(--ba);
  color:var(--t2);font-size:1.2rem;cursor:pointer;
  display:flex;align-items:center;justify-content:center;
  transition:all .2s;
}
.theme-toggle:hover{background:var(--bg4);color:var(--t);border-color:var(--ac)}

/* --- Editorial / Dossier Components --- */
.eyebrow,.section-kicker{
  display:inline-flex;align-items:center;gap:0.45rem;
  color:var(--am);font-family:"JetBrains Mono",monospace;font-size:0.72rem;font-weight:800;
  letter-spacing:0.12em;text-transform:uppercase;margin-bottom:1rem;
}
.eyebrow::before,.section-kicker::before{content:'';width:0.55rem;height:0.55rem;border-radius:50%;background:currentColor;box-shadow:0 0 24px currentColor}
.dossier-hero{position:relative;min-height:100vh;padding:7rem 2rem 4rem;display:flex;align-items:center;overflow:hidden}
.dossier-hero::before{content:'';position:absolute;inset:0;background:radial-gradient(circle at 70% 30%,rgba(34,211,238,0.12),transparent 28rem),linear-gradient(90deg,rgba(7,10,15,0.95),rgba(7,10,15,0.58));pointer-events:none}
.hero-grid{position:relative;z-index:1;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(320px,0.72fr);gap:3rem;align-items:center;max-width:1180px;width:100%;margin:0 auto}
.thesis{font-size:clamp(1.05rem,1.8vw,1.28rem);max-width:740px;color:var(--t2);line-height:1.7;margin:1.2rem 0 1.5rem}
.proof-ledger{background:linear-gradient(180deg,rgba(16,23,34,0.94),rgba(7,10,15,0.94));border:1px solid var(--ba);border-radius:24px;padding:1.2rem;box-shadow:var(--panel-shadow)}
.proof-ledger h3{margin:0 0 0.8rem;font-family:"JetBrains Mono",monospace;font-size:0.78rem;text-transform:uppercase;letter-spacing:0.09em;color:var(--t3)}
.proof-card{display:grid;grid-template-columns:1fr auto;gap:1rem;align-items:center;padding:1rem;border:1px solid var(--b);border-radius:16px;background:rgba(255,255,255,0.025);margin-top:0.7rem}
.proof-card:first-of-type{margin-top:0}
.proof-card .label{font-size:0.8rem;color:var(--t2);font-weight:700}
.proof-card .detail{display:block;font-size:0.72rem;color:var(--t3);margin-top:0.15rem;line-height:1.4}
.proof-card .value{font-size:1.35rem;font-weight:850;color:var(--ac);font-family:"JetBrains Mono",monospace;letter-spacing:-0.04em;text-align:right}
.proof-card.market .value{color:var(--am)}
.proof-card.success .value{color:var(--success)}
.dossier-section{padding:5rem 2rem;position:relative}
.dossier-section.alt{background:rgba(11,17,26,0.62)}
.dossier-inner{max-width:1120px;margin:0 auto}.dossier-inner.narrow{max-width:880px}
.split-copy{display:grid;grid-template-columns:0.8fr 1.2fr;gap:2rem;align-items:start}
.receipt-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:1rem;margin-top:1.5rem}
.receipt{background:linear-gradient(180deg,rgba(16,23,34,0.96),rgba(11,17,26,0.96));border:1px solid var(--b);border-top:3px solid var(--ac);border-radius:18px;padding:1.25rem;text-align:left;box-shadow:0 1px 0 rgba(255,255,255,0.03) inset}
.receipt.market{border-top-color:var(--am)}.receipt.success{border-top-color:var(--success)}.receipt.cyan{border-top-color:var(--cy)}
.receipt .claim{font-size:0.72rem;color:var(--t3);font-family:"JetBrains Mono",monospace;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:0.75rem}
.receipt .measure{font-size:1.6rem;font-weight:850;color:var(--t);letter-spacing:-0.04em;line-height:1}
.receipt .measure.ac{color:var(--ac)}.receipt .measure.amber{color:var(--am)}.receipt .measure.green{color:var(--success)}
.receipt p{font-size:0.84rem;line-height:1.6;margin:0.75rem 0 0;color:var(--t2)}
.comparison-panel{display:grid;grid-template-columns:1fr 1fr;gap:1px;overflow:hidden;border:1px solid var(--b);border-radius:22px;background:var(--b);box-shadow:var(--panel-shadow);margin-top:1.5rem}
.comparison-panel>div{background:rgba(16,23,34,0.96);padding:1.4rem}
.comparison-panel h3{font-size:0.78rem;color:var(--t3);font-family:"JetBrains Mono",monospace;text-transform:uppercase;letter-spacing:0.08em;margin:0 0 1rem}
.comparison-panel p{font-size:0.88rem;margin:0;color:var(--t2)}
.comparison-panel strong{color:var(--t)}
.pullquote{background:linear-gradient(135deg,rgba(245,158,11,0.08),rgba(34,211,238,0.05));border:1px solid var(--ba);border-left:4px solid var(--am);border-radius:0 20px 20px 0;padding:1.4rem 1.6rem;color:var(--t);font-size:1.05rem;line-height:1.55;margin:1.5rem 0}
.chapter-list{display:grid;gap:0.85rem;margin-top:1.5rem}
.chapter{display:grid;grid-template-columns:4rem 1fr;gap:1rem;padding:1rem 1.1rem;border:1px solid var(--b);border-radius:16px;background:rgba(16,23,34,0.86);text-align:left}
.chapter-num{font-family:"JetBrains Mono",monospace;color:var(--ac);font-size:1.45rem;font-weight:850;line-height:1}
.chapter h3{margin:0 0 0.25rem}.chapter p{margin:0;font-size:0.86rem;color:var(--t2)}

/* === Shared page components (consolidated from page <style> blocks) === */

.pulse{display:inline-flex;align-items:center;gap:0.5rem;padding:0.3rem 1rem;background:rgba(34,211,238,0.06);border:1px solid rgba(34,211,238,0.15);border-radius:100px;font-size:0.72rem;font-weight:600;letter-spacing:0.5px;color:var(--ac);margin-bottom:1.5rem;text-transform:uppercase}
.pulse .dot{width:6px;height:6px;border-radius:50%;background:var(--ac);animation:pulse 2s infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.35}}
.fsec{padding:4rem 2rem;position:relative}
.fsec:nth-child(even){background:var(--bg2)}.fsec:nth-child(odd){background:var(--bg)}
.inr{position:relative;z-index:1;max-width:960px;width:100%;margin:0 auto}.inr.wide{max-width:1100px}
.bar{height:4px;border-radius:2px;margin:0.5rem 0;background:rgba(255,255,255,0.06);overflow:hidden}
.bar .fill{height:100%;border-radius:2px;transition:width .5s;background:var(--ac)}
.bar .fill.amber{background:var(--am)}.bar .fill.cyan{background:var(--cy)}

/* === Floating Table of Contents (bottom-right button + slide panel) === */
.toc-float {
  position: fixed; bottom: 1.5rem; right: 4.5rem; z-index: 190;
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--bg3); border: 1px solid var(--ba);
  color: var(--t2); font-size: 1.4rem; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
